import app from 'flarum/forum/app';
import { extend } from 'flarum/common/extend';
import extractText from 'flarum/common/utils/extractText';
import DiscussionControls from 'flarum/forum/utils/DiscussionControls';
import PostControls from 'flarum/forum/utils/PostControls';
import UserControls from 'flarum/forum/utils/UserControls';
import Button from 'flarum/common/components/Button';
import { absoluteUrl } from '../helpers/url';
async function shareContent(data) {
  try {
    await navigator.share({
      title: extractText(data.title),
      url: data.url
    });
  } catch (err) {
    console.error('[fof-pwa] Share failed:', err);
  }
}
export default function addShareControls() {
  extend(DiscussionControls, 'userControls', function (items, discussion) {
    items.add('share', m(Button, {
      icon: "fas fa-share-square",
      onclick: () => shareContent({
        title: discussion.title(),
        url: absoluteUrl(app.route.discussion(discussion))
      })
    }, app.translator.trans('fof-pwa.forum.discussion_controls.share_button')), -1);
  });
  extend(PostControls, 'userControls', function (items, post) {
    if (!post.user() || !post.discussion()) return;
    items.add('share', m(Button, {
      icon: "fas fa-share-square",
      onclick: () => shareContent({
        title: app.translator.trans('fof-pwa.forum.post_controls.share_api.title', {
          username: post.user().displayName(),
          title: post.discussion().title()
        }),
        url: absoluteUrl(app.route.post(post))
      })
    }, app.translator.trans('fof-pwa.forum.post_controls.share_button')), 100);
  });
  extend(UserControls, 'userControls', function (items, user) {
    if (!user) return;
    items.add('share', m(Button, {
      icon: "fas fa-share-square",
      onclick: () => shareContent({
        title: user.displayName(),
        url: absoluteUrl(app.route.user(user))
      })
    }, app.translator.trans('fof-pwa.forum.user_controls.share_button')), 100);
  });
}
flarum.reg.add('fof-pwa', 'forum/share/addShareControls', addShareControls);